sys_variable_value.value:
(function execute(inputs, outputs) {

    var response = JSON.parse(inputs.response_body);

    outputs.payment_status = response.status || "";
    outputs.transaction_id = response.transaction_id || "";
    outputs.payment_message = response.message ||
        (response.status === "SUCCESS" ? "Payment processed successfully" : "Payment failed");

})(inputs, outputs);

